import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and represents a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  if (Number.isNaN(date.getTime())) return false;
  const [year, month, day] = dateStr.split('-').map(Number);
  return date.getUTCFullYear() === year && date.getUTCMonth() + 1 === month && date.getUTCDate() === day;
}

/**
 * Validate discount percent (0-100, can be decimal).
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return true;
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the total for a single line: qty * unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customerId
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate SKU and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return { subtotal, total: subtotal };
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const product = productResult.value;
  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: [],
  };

  // Check if SKU already exists
  let found = false;
  for (const line of invoice.lines) {
    if (line.sku === sku) {
      newInvoice.lines.push({
        sku: line.sku,
        name: line.name,
        qty: line.qty + qty,
        unitPrice: line.unitPrice,
        vatRate: line.vatRate,
      });
      found = true;
    } else {
      newInvoice.lines.push({ ...line });
    }
  }

  // If SKU wasn't found, add new line
  if (!found) {
    newInvoice.lines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find and remove the line
  const newLines = [];
  let found = false;
  for (const line of invoice.lines) {
    if (line.sku === sku) {
      found = true;
    } else {
      newLines.push({ ...line });
    }
  }

  // Check if SKU was found
  if (!found) return fail('LINE_NOT_FOUND');

  // Check if this would remove the last line
  if (newLines.length === 0) return fail('NO_LINES');

  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    number,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  };

  return ok(newInvoice);
}

