  assert.ok(text.includes('Discount: -€9,500.00'));
  assert.ok(text.includes('Total: €40,000.00'));
});

test('renderInvoiceText does not show discount section when zero', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(!text.includes('Discount:'));
});

test('renderInvoiceText calculates correct total with discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 3, discountPercent: 50 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('€3,600.00'));
  assert.ok(text.includes('50% off: -€1,800.00'));
  assert.ok(text.includes('Discount: -€1,800.00'));
  assert.ok(text.includes('Total: €1,800.00'));
});

test('renderInvoiceText handles decimal discount percent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 12.5 },
